toolCall.argumentsJson:
{"CommandLine":"Stop-Process -Name "PROGRAMA_PERFECTO_XVIEW_B866V2" -Force -ErrorAction SilentlyContinue
$exePath = "c:\Users\andre\OneDrive\Desktop\xview\programa perfecto\PROGRAMA_PERFECTO_XVIEW_B866V2.exe"
$workDir = "c:\Users\andre\OneDrive\Desktop\xview\programa perfecto"
$logFile = "c:\Users\andre\OneDrive\Desktop\xview\programa perfecto\BITACORA_EN_VIVO_EXE.log"

$p = Start-Process -FilePath $exePath -WorkingDirectory $workDir -PassThru
Start-Sleep -Milliseconds 700
Add-Type @"
using System;
using System.Runtime.InteropServices;
public class WinFg2 {
    [DllImport("user32.dll")]
    public static extern bool SetForegroundWindow(IntPtr hWnd);
}
"@
if ($p -and $p.MainWindowHandle -ne [IntPtr]::Zero) {
    [WinFg2]::SetForegroundWindow($p.MainWindowHandle) | Out-Null
}
Write-Host "[ACTIVO] Ventana interactiva abierta en tu escritorio (PID=$($p.Id))"

$lastLen = 0
if (Test-Path $logFile) { $lastLen = (Get-Item $logFile).Length }

while (-not $p.HasExited) {
    if (Test-Path $logFile) {
        $item = Get-Item $logFile
        if ($item.Length -gt $lastLen) {
            $fs = [System.IO.File]::Open($logFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
            $fs.Seek($lastLen, [System.IO.SeekOrigin]::Begin) | Out-Null
            $sr = New-Object System.IO.StreamReader($fs, [System.Text.Encoding]::UTF8)
            $newText = $sr.ReadToEnd()
            $sr.Close()
            $fs.Close()
            $lastLen = $item.Length
            if ($newText) {
                Write-Host -NoNewline $newText
            }
        }
    }
    Start-Sleep -Milliseconds 500
}
Write-Host "[CERRADO] El usuario cerro PROGRAMA_PERFECTO_XVIEW_B866V2.exe (PID=$($p.Id))."","IsDaemon":true,"WaitMsBeforeAsync":2500,"toolSummary":"Launch interactive window and monitor live session"}
